// Local Expo config plugin: the Android build refuses to run with an unpatched library (decision D247).
//
// `apps/mobile/android/` is regenerated by `expo prebuild`, so the guard is re-applied here as one marked
// block at the end of `android/app/build.gradle` (idempotent: the marker is checked first). The block adds
// the task `demsCheckLibraryPatches` and makes `preBuild` depend on it, so every variant (debug, release)
// fails before anything is compiled or packaged when
// - react-native-reanimated is not exactly the version the repository's patch was made for, or
// - the marker the patch writes into the library source is absent.
// The patch itself is applied by `apps/mobile/scripts/apply-patches.sh` (root `postinstall`); the version,
// marker and file below are the same three values that script holds. See apps/mobile/patches/README.md.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '@dems-library-patches';
const LIB_NAME = 'react-native-reanimated';
const LIB_VERSION = '4.5.1';
const PATCH_MARKER = `DEMS-PATCH ${LIB_NAME}+${LIB_VERSION}`;
const MARKED_FILE = 'android/src/main/java/com/swmansion/reanimated/NativeProxy.kt';

const GUARD_BLOCK = `
// ${MARKER}: generated by apps/mobile/plugins/with-dems-library-patches.js (decision D247). Do not edit here.
def demsCheckLibraryPatches = tasks.register("demsCheckLibraryPatches") {
    doLast {
        def demsLibPackage = new File(["node", "--print", "require.resolve('${LIB_NAME}/package.json')"].execute(null, rootDir).text.trim())
        if (!demsLibPackage.isFile()) {
            throw new GradleException("DEMS: ${LIB_NAME} was not found from " + rootDir + ". Run npm ci, then apps/mobile/scripts/apply-patches.sh.")
        }
        def demsLibVersion = new groovy.json.JsonSlurper().parse(demsLibPackage).version
        if (demsLibVersion != "${LIB_VERSION}") {
            throw new GradleException("DEMS: ${LIB_NAME} is version '" + demsLibVersion + "', and the patch is for exactly ${LIB_VERSION}. Do not build: read apps/mobile/patches/README.md (check whether the new version still needs the patch, then re-make or remove it).")
        }
        def demsPatchedFile = new File(demsLibPackage.getParentFile(), "${MARKED_FILE}")
        if (!demsPatchedFile.isFile() || !demsPatchedFile.getText("UTF-8").contains("${PATCH_MARKER}")) {
            throw new GradleException("DEMS: ${LIB_NAME} ${LIB_VERSION} is NOT patched. Run apps/mobile/scripts/apply-patches.sh; an unpatched library must not be packaged.")
        }
    }
}
tasks.named("preBuild").configure { dependsOn(demsCheckLibraryPatches) }
`;

/** Appends the guard block once; a second run leaves the file unchanged. */
function applyDemsLibraryPatchGuard(contents) {
  if (contents.includes(MARKER)) return contents;
  return `${contents.replace(/\s*$/, '\n')}${GUARD_BLOCK}`;
}

function withDemsLibraryPatches(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('with-dems-library-patches: android/app/build.gradle is not Groovy; update the plugin.');
    }
    mod.modResults.contents = applyDemsLibraryPatchGuard(mod.modResults.contents);
    return mod;
  });
}

module.exports = withDemsLibraryPatches;
module.exports.applyDemsLibraryPatchGuard = applyDemsLibraryPatchGuard;
module.exports.MARKER = MARKER;
module.exports.LIB_VERSION = LIB_VERSION;
module.exports.PATCH_MARKER = PATCH_MARKER;
